package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.integration.github.v1.GitHubCommitImportedV1;
class GitHubActivityTest extends ActivityFixtures {
 @Test void importedObservationKeepsOwnPrivateScopeAndGitTimeSeparateFromImportTime(){var raw=wire("GITHUB_COMMIT",id());var e=ActivityEvent.decode("integration.github-commit.v1",raw);assertTrue(GitHubActivity.target(e));assertEquals("integration",ActivityEvent.group(e.kind()));assertEquals("IMPORTED",e.state());assertEquals("GitHubCommitImported",e.eventType());assertTrue(e.detail().contains("2020-01-01T00:00:00Z"));assertTrue(e.detail().contains("본인의 기여로 간주하지 않습니다"));assertNull(e.planning());assertNull(e.roadmapId());ActivityEvent.transport("integration.github-commit.v1",raw,e.aggregateId().toString(),headers(e));}
 @Test void privateUpstreamSourceWrongIdsTimesAndUrlsNeverBecomeTimelineEntries()throws Exception{var raw=wire("GITHUB_COMMIT",id());var e=RoadmapEventEnvelopeV1.parseFrom(raw);var p=GitHubCommitImportedV1.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setSourceVisibility("PRIVATE"),p.toBuilder().setRepositoryId("bad"),p.toBuilder().setCommitId(id().toString()),p.toBuilder().setSha("bad"),p.toBuilder().setUrl("https://evil.test/"),p.toBuilder().setVersion(2),p.toBuilder().setImportedAt("2020-01-01T00:00:00Z"))){assertThrows(RuntimeException.class,()->ActivityEvent.decode("integration.github-commit.v1",e.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}}
 @Test void githubCursorCannotBeReusedForAnotherSpaceOrEventKind(){var e=ActivityEvent.decode("integration.github-commit.v1",wire("GITHUB_COMMIT",id()));var p=ActivityQueryTest.params("kind","GITHUB_COMMIT");var q=ActivityQuery.parse(e.spaceId(),p);p.put("before",new String[]{q.cursor(e)});assertEquals(e.eventId(),ActivityQuery.parse(e.spaceId(),p).event());assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),p));p.put("kind",new String[]{"TASK"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(e.spaceId(),p));}
}
